parameters.jsCode:
// Read persistent cursor (workflow-static data). On first run, default to (now - 6min)
// to give a 1-min overlap with the schedule (5 min) so a late tick doesn't miss anything.
const staticData = $getWorkflowStaticData('global');
const nowMs = Date.now();
const defaultSinceMs = nowMs - 6 * 60 * 1000;
const sinceMs = (typeof staticData.lastSeenMs === 'number' && staticData.lastSeenMs > 0)
  ? staticData.lastSeenMs
  : defaultSinceMs;
return [{ json: {
  sinceMs,
  nowMs,
  channelId: 'qoia7dfowb8q9n16ukkidb874c',
  chrisBotUserId: 'b5jiw3sk13rbibcbt4t98gf1ra',
  dmChannelId: 'cqhn533i8tnszryak11ysnkj3r',
  mattermostBase: 'https://chat.birdmug.com/api/v4'
} }];

// Filter to *new chris-bot posts that @-mention kyle-bot*, advance cursor.
const staticData = $getWorkflowStaticData('global');
const ctx = $('Compute Cursor').first().json;

const apiResp = $json;
// HTTPError surface — if HTTP errored, $json may be the error envelope; refuse to silently treat as empty.
if (apiResp && apiResp.error) {
  throw new Error('Mattermost API error fetching channel posts: ' + JSON.stringify(apiResp.error));
}
if (!apiResp || !('order' in apiResp) || !('posts' in apiResp)) {
  throw new Error('Mattermost response missing expected keys (got ' + Object.keys(apiResp || {}).join(',') + ')');
}

const order = Array.isArray(apiResp.order) ? apiResp.order : [];
const posts = apiResp.posts || {};

// Walk in chronological order so the cursor advance is monotonic.
const chronological = [...order].reverse();
let maxCreate = ctx.sinceMs;
const urgent = [];

for (const pid of chronological) {
  const p = posts[pid];
  if (!p) continue;
  if (p.create_at <= ctx.sinceMs) continue; // safety: belt-and-suspenders since the query already filters
  if (p.create_at > maxCreate) maxCreate = p.create_at;

  // Only care about chris-bot's posts
  if (p.user_id !== ctx.chrisBotUserId) continue;
  // Skip system messages (joined/left etc.)
  if (p.type && p.type !== '') continue;
  // Must @-mention kyle-bot
  const msg = (p.message || '').toString();
  if (!msg.includes('@kyle-bot')) continue;

  urgent.push({
    post_id: p.id,
    create_at: p.create_at,
    message: msg,
    excerpt: msg.length > 280 ? msg.slice(0, 277) + '…' : msg,
    permalink: 'https://chat.birdmug.com/birdmugcom/channels/orthos?postid=' + p.id,
    dmChannelId: ctx.dmChannelId,
    mattermostBase: ctx.mattermostBase
  });
}

// Advance cursor regardless — we've seen everything up to maxCreate, urgent or not.
staticData.lastSeenMs = maxCreate;

return urgent.length
  ? urgent.map(u => ({ json: u }))
  : [];

